add('d31','duas','الهداية والثبات','الهدى والتقى','اللهم إني أسألك الهدى والتقى والعفاف والغنى.','صحيح مسلم • 2721');
add('d32','duas','جوامع الدعاء','إصلاح الدين والدنيا','اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي، واجعل الحياة زيادة لي في كل خير، واجعل الموت راحة لي من كل شر.','صحيح مسلم • 2720');
add('d33','duas','الكرب والشفاء','دعاء الشفاء','اللهم رب الناس، أذهب البأس، اشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقمًا.','صحيح البخاري • 5743');
add('d34','duas','المغفرة والتوبة','سؤال العفو','اللهم إنك عفو تحب العفو فاعف عني.','جامع الترمذي • 3513');
add('d35','duas','الرزق والبركة','الاستغناء بحلال الله','اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمن سواك.','جامع الترمذي • 3563');
add('d36','duas','الهداية والثبات','العون على الذكر والشكر','اللهم أعني على ذكرك وشكرك وحسن عبادتك.','سنن أبي داود • 1522');
add('d37','duas','الكرب والشفاء','الاستعاذة من الهم','اللهم إني أعوذ بك من الهم والحزن، والعجز والكسل، والبخل والجبن، وضلع الدين، وغلبة الرجال.','صحيح البخاري • 6369');
add('d38','duas','المغفرة والتوبة','المغفرة الشاملة','اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره.','صحيح مسلم • 483');
add('d39','duas','الهداية والثبات','طلب الهدى والسداد','اللهم اهدني وسددني.','صحيح مسلم • 2725');
add('d40','duas','العلم والحكمة','العلم النافع','اللهم إني أعوذ بك من علم لا ينفع، ومن قلب لا يخشع، ومن نفس لا تشبع، ومن دعوة لا يستجاب لها.','صحيح مسلم • 2722');
add('a1','athkar','الصباح','ذكر الصباح','أصبحنا وأصبح الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير. رب أسألك خير ما في هذا اليوم وخير ما بعده، وأعوذ بك من شر ما في هذا اليوم وشر ما بعده. رب أعوذ بك من الكسل وسوء الكبر، رب أعوذ بك من عذاب في النار وعذاب في القبر.','صحيح مسلم • 2723');
add('a2','athkar','المساء','ذكر المساء','أمسينا وأمسى الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير. رب أسألك خير ما في هذه الليلة وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها. رب أعوذ بك من الكسل وسوء الكبر، رب أعوذ بك من عذاب في النار وعذاب في القبر.','صحيح مسلم • 2723');
for(const c of ['الصباح','المساء']){
add('aykursi'+c,'athkar',c,'آية الكرسي',null,'القرآن الكريم • البقرة 255',1,[2,255,255]);
for(const s of [112,113,114])add('aq'+c+s,'athkar',c,{112:'سورة الإخلاص',113:'سورة الفلق',114:'سورة الناس'}[s],null,'القرآن الكريم • عدد التكرار: سنن أبي داود 5082',3,[s,1,s===112?4:s===113?5:6]);
add('ist'+c,'athkar',c,'سيد الاستغفار','اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شر ما صنعت، أبوء لك بنعمتك علي، وأبوء بذنبي، فاغفر لي، فإنه لا يغفر الذنوب إلا أنت.','صحيح البخاري • 6306');
add('bism'+c,'athkar',c,'الاستعاذة بالله','بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم.','سنن أبي داود • 5088',3);
add('sub'+c,'athkar',c,'تسبيح وتحميد','سبحان الله وبحمده.','صحيح مسلم • 2692',100);
}
