add('r8','ruqyah','الدعاء','الرقية من الألم','بسم الله.','صحيح مسلم • 2202: يضع يده على موضع الألم ويقول بسم الله ثلاثًا',3);
add('r9','ruqyah','الدعاء','الاستعاذة من الألم','أعوذ بالله وقدرته من شر ما أجد وأحاذر.','صحيح مسلم • 2202',7);
add('r10','ruqyah','الدعاء','دعاء الرقية','بسم الله أرقيك، من كل شيء يؤذيك، من شر كل نفس أو عين حاسد، الله يشفيك، بسم الله أرقيك.','صحيح مسلم • 2186');
